using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Web.Script.Serialization;
class MemoryProtectionQA{
 static int checks;
 static void Assert(bool ok,string message){checks++;if(!ok)throw new Exception("FAIL "+message);Console.WriteLine("PASS "+message);}
 static Process Start(string exe){var child=Process.Start(new ProcessStartInfo(exe){UseShellExecute=false,RedirectStandardInput=true,RedirectStandardOutput=true,CreateNoWindow=true});Assert(child.StandardOutput.ReadLine()=="READY","owned fixture starts");return child;}
 static Dictionary<string,object> P(){return new Dictionary<string,object>{{"deviceId","local"}};}
 static MemoryMaintenance.Status Status(MemoryMaintenance s){return (MemoryMaintenance.Status)s.Request("memory.status",P());}
 static Dictionary<string,object> Identity(MemoryMaintenance.ProcessRow row){var p=P();p["pid"]=row.pid;p["path"]=row.path;p["startTicks"]=row.startIdentity;return p;}
 static void Denied(Action run,string message){bool denied=false;try{run();}catch(InvalidOperationException){denied=true;}catch(ArgumentException){denied=true;}Assert(denied,message);}
 static int Main(string[] args){Process first=null,second=null,other=null;try{string root=args[0],exe=args[1];Directory.CreateDirectory(root);first=Start(exe);string otherDir=Path.Combine(root,"other");Directory.CreateDirectory(otherDir);string otherExe=Path.Combine(otherDir,"Fixture.exe");File.Copy(exe,otherExe);other=Start(otherExe);string[] areas={"workset","filecache","modified","registry","combine","standby"};
  using(var s=new MemoryMaintenance(root)){
   var status=Status(s);Assert(status.capabilities.Count==7,"seven real area implementations exposed");var row=status.processes.Single(p=>p.pid==first.Id);Assert(row.startIdentity==row.startTicks.ToString(),"creation identity serialized losslessly as a string");Assert(row.canProtect&&row.canTerminate,"owned fixture exposes allowed actions");
   var prepare=P();prepare["areas"]=new[]{"workset"};prepare["pids"]=new[]{first.Id};var plan=(MemoryMaintenance.Confirmation)s.Request("memory.prepare",prepare);
   var protect=Identity(row);protect["protected"]=true;s.Request("memory.process.protect",protect);status=Status(s);var kept=status.processes.Single(p=>p.pid==first.Id);Assert(kept.protectedProgram&&!kept.canTrim&&!kept.canTerminate&&kept.canProtect,"retained executable cannot be trimmed or terminated and can be released");Assert(status.processes.Single(p=>p.pid==other.Id).canTrim,"same filename at a different full path is independent");
   Denied(()=>s.Request("memory.process.terminate",Identity(row)),"retained executable rejects explicit termination");Denied(()=>s.Request("memory.prepare",prepare),"new cleanup plan excludes retained executable");
   var execute=P();execute["token"]=plan.token;var result=(MemoryMaintenance.Record)s.Request("memory.execute",execute);Assert(result.results[0].succeeded==0&&result.results[0].skipped==1,"old confirmation rechecks newly protected executable before execution");first.StandardInput.WriteLine("VERIFY");Assert(first.StandardOutput.ReadLine()=="VALID"&&!first.HasExited,"protected owned fixture remains alive with intact allocations");
   var select=P();select["areas"]=areas;s.Request("memory.selection.save",select);var policy=P();policy["enabled"]=false;policy["threshold"]=90;policy["durationMinutes"]=5;policy["cooldownMinutes"]=30;policy["areas"]=areas;s.Request("memory.policy.save",policy);
   var stale=Identity(row);stale["startTicks"]=(row.startTicks+1).ToString();Denied(()=>s.Request("memory.process.terminate",stale),"stale creation identity rejects termination");var mismatch=Identity(row);mismatch["path"]=otherExe;Denied(()=>s.Request("memory.process.protect",mismatch),"mismatched executable path rejected");var self=status.processes.Single(p=>p.pid==Process.GetCurrentProcess().Id);Denied(()=>s.Request("memory.process.terminate",Identity(self)),"application itself cannot be terminated");Assert(status.processes.Where(p=>p.intrinsicProtection).All(p=>!p.canProtect&&!p.canTerminate&&!p.canTrim),"intrinsic system and application exclusions have no destructive actions");
  }
  first.StandardInput.WriteLine("EXIT");Assert(first.WaitForExit(5000),"first fixture exits by its own command");second=Start(exe);Assert(first.Id!=second.Id,"fixture restarted with a new PID");
  using(var s=new MemoryMaintenance(root)){var status=Status(s);Assert(status.manualAreas.SequenceEqual(areas)&&status.policy.areas.SequenceEqual(areas),"manual choices and automatic choices survive service restart");var row=status.processes.Single(p=>p.pid==second.Id);Assert(row.protectedProgram&&!row.canTrim,"full-path protection survives service and process restart");var release=Identity(row);release["protected"]=false;s.Request("memory.process.protect",release);row=Status(s).processes.Single(p=>p.pid==second.Id);Assert(!row.protectedProgram&&row.canTrim&&row.canTerminate,"release restores owned fixture capabilities");s.Request("memory.process.terminate",Identity(row));Assert(second.WaitForExit(3000),"explicit termination immediately ends only the owned fixture");Assert(!other.HasExited,"same-name fixture at other path remains alive");Denied(()=>s.Request("memory.process.terminate",Identity(row)),"exited process identity cannot be reused");var select=P();select["areas"]=new string[0];s.Request("memory.selection.save",select);}
  using(var s=new MemoryMaintenance(root)){Assert(Status(s).manualAreas.Length==0,"all-deselected manual choices survive restart");}
  File.WriteAllText(Path.Combine(root,"protection-summary.json"),new JavaScriptSerializer().Serialize(new{result="PASS",checks,terminatedOnlyOwnedFixture=true,systemCachesExecuted=false,automaticExecutionTested=false}));Console.WriteLine("PROTECTION_CHECKS="+checks);return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{foreach(var p in new[]{first,second,other})if(p!=null){try{if(!p.HasExited){p.StandardInput.WriteLine("EXIT");if(!p.WaitForExit(5000))p.Kill();}}catch{}p.Dispose();}}}
}
